#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/swift/tasks/test-golden-swift.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Compare the views of the Xcode app against their golden images; --record records them again"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--record" help="record every golden again, then compare against the new ones"

import glob
import os
import re
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402
import xcode  # noqa: E402

os.chdir(os.environ["MISE_PROJECT_ROOT"])

# Shipped with the swift tool. Its one flag is --record, because test:golden
# passes the same arguments to each part. It reads these values, with a
# default; a repository sets them in the [env] of
# .config/mise/conf.d/zz-repo/mise.<env>.toml:
#   XCODE_SCHEME           the scheme whose test action holds the target (the
#                          name of the project)
#   XCODE_SNAPSHOT_TARGET  the snapshot test target to run (SnapshotTests)
#   SIMULATOR_PLATFORM, SIMULATOR_DEVICE, SIMULATOR_OS
#                          the simulator to render on; see _scripts/xcode.py
#
# Without an *.xcodeproj at the root, the part does not apply and prints
# nothing. With one, it applies: more than one *.xcodeproj or no Xcode stops
# it with code 1, and a project without the target XCODE_SNAPSHOT_TARGET
# prints nothing.
if not any(os.path.isdir(p) for p in glob.glob("*.xcodeproj")):
  sys.exit(0)

project = xcode.find_xcodeproj("test:golden")
xcode.require_xcode("test:golden")
target = os.environ.get("XCODE_SNAPSHOT_TARGET") or "SnapshotTests"

# The targets are the lines below "Targets:" of xcodebuild -list, up to the
# first empty line. A failed xcodebuild stops the part with its code.
listed = subprocess.run(
  ["xcodebuild", "-list", "-project", project], check=False, stdout=subprocess.PIPE, text=True, errors="replace"
)
if listed.returncode != 0:
  sys.exit(listed.returncode)
found = False
in_targets = False
for line in listed.stdout.split("\n"):
  if re.match(r" *Targets:", line):
    in_targets = True
    continue
  if in_targets and re.fullmatch(r" *", line):
    in_targets = False
  if in_targets and line.strip(" ") == target:
    found = True
    break
if not found:
  sys.exit(0)

scheme = os.environ.get("XCODE_SCHEME") or os.path.basename(project).removesuffix(".xcodeproj")
record = os.environ.get("usage_record") == "true"

if record:
  helpers.print_header("Recording and comparing the Swift goldens ...")
else:
  helpers.print_header("Comparing the Swift goldens ...")

platform = os.environ["SIMULATOR_PLATFORM"]
if platform == "macOS":
  destination = "platform=macOS"
elif not os.environ.get("SIMULATOR_DEVICE") or not os.environ.get("SIMULATOR_OS"):
  helpers.print_error(
    f"test:golden: the {platform} pin is incomplete - SIMULATOR_DEVICE and SIMULATOR_OS are both required."
  )
  helpers.print_yellow(
    "Set SIMULATOR_DEVICE and SIMULATOR_OS in the [env] of .config/mise/conf.d/zz-repo/mise.<env>.toml;"
    " xcrun simctl list devices available lists the choices."
  )
  sys.exit(1)
else:
  # require_xcode defaults the platform to iOS; xcodebuild names it
  # "iOS Simulator".
  destination_platform = "iOS Simulator" if platform == "iOS" else platform
  destination = f"platform={destination_platform},name={os.environ['SIMULATOR_DEVICE']},OS={os.environ['SIMULATOR_OS']}"
helpers.print_info(f"Destination: {destination}")

artifacts = f"{os.path.abspath(os.environ['MISE_PROJECT_ROOT'])}/.build/snapshot-artifacts"
result_bundle = ".build/golden.xcresult"


def run_goldens(mode):
  """Run the snapshot target once with the record mode mode; return its code."""
  shutil.rmtree(result_bundle, ignore_errors=True)
  # xcodebuild strips TEST_RUNNER_ and hands the rest to the tests.
  env = dict(os.environ, TEST_RUNNER_SNAPSHOT_TESTING_RECORD=mode, TEST_RUNNER_SNAPSHOT_ARTIFACTS=artifacts)
  return subprocess.run(
    [
      "xcodebuild",
      "test",
      "-project",
      project,
      "-scheme",
      scheme,
      "-destination",
      destination,
      f"-only-testing:{target}",
      "-derivedDataPath",
      ".build/DerivedData",
      "-clonedSourcePackagesDirPath",
      ".build/SourcePackages",
      "-onlyUsePackageVersionsFromResolvedFile",
      "-resultBundlePath",
      result_bundle,
      "-collect-test-diagnostics",
      "never",
    ],
    check=False,
    env=env,
  ).returncode


if record:
  helpers.print_subheader("Recording the goldens ...")
  # Recording fails every assertion by design; the comparison below is the
  # verdict.
  run_goldens("all")
  helpers.print_subheader("Comparing the goldens ...")

shutil.rmtree(artifacts, ignore_errors=True)
os.makedirs(artifacts, exist_ok=True)
sys.exit(run_goldens("never"))
